import{_ as t,c as r,o as a,ah as s,j as e,a as n}from"./chunks/framework.oAolcYhj.js";const d="/Qonnectra-docs/pr-14/images/manual/teil-a/map_opacity.jpg",l="/Qonnectra-docs/pr-14/images/manual/teil-a/map_legend.jpg",h="/Qonnectra-docs/pr-14/images/manual/teil-a/map_legend_actions.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/map_address_detail.jpg",c="/Qonnectra-docs/pr-14/images/manual/teil-a/map_address_detail_select.jpg",u="/Qonnectra-docs/pr-14/images/manual/teil-a/map_search.jpg",m="/Qonnectra-docs/pr-14/images/manual/teil-a/map_search_flow.jpg",b="/Qonnectra-docs/pr-14/videos/map_attachment.webm",D=JSON.parse('{"title":"3. Wiederkehrende Bedienelemente","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/03-wiederkehrende-bedienelemente.md","filePath":"manual/teil-a-anwenderhandbuch/03-wiederkehrende-bedienelemente.md"}'),p={name:"manual/teil-a-anwenderhandbuch/03-wiederkehrende-bedienelemente.md"};function g(f,i,k,S,_,z){return a(),r("div",null,[...i[0]||(i[0]=[s('<h1 id="_3-wiederkehrende-bedienelemente" tabindex="-1">3. Wiederkehrende Bedienelemente <a class="header-anchor" href="#_3-wiederkehrende-bedienelemente" aria-label="Permalink to &quot;3. Wiederkehrende Bedienelemente&quot;">​</a></h1><p>Einige Bedienelemente von Qonnectra tauchen in mehreren Ansichten unverändert auf: das Kartenfenster mit seiner Legende, die Objektsuche, der Infobereich am rechten Rand und die Anhänge. Dieses Kapitel beschreibt sie einmal; die Kapitel zu den einzelnen Menüpunkten verweisen darauf und nennen nur noch, was dort davon abweicht.</p><h2 id="_3-1-tabellen-suche-spaltenfilter-sortierung-seitenwechsel" tabindex="-1">3.1 Tabellen: Suche, Spaltenfilter, Sortierung, Seitenwechsel <a class="header-anchor" href="#_3-1-tabellen-suche-spaltenfilter-sortierung-seitenwechsel" aria-label="Permalink to &quot;3.1 Tabellen: Suche, Spaltenfilter, Sortierung, Seitenwechsel&quot;">​</a></h2><p><em>Die Dokumentation zu diesem Abschnitt ist noch in Arbeit.</em></p><h2 id="_3-2-auswahllisten-und-kombinationsfelder" tabindex="-1">3.2 Auswahllisten und Kombinationsfelder <a class="header-anchor" href="#_3-2-auswahllisten-und-kombinationsfelder" aria-label="Permalink to &quot;3.2 Auswahllisten und Kombinationsfelder&quot;">​</a></h2><p><em>Die Dokumentation zu diesem Abschnitt ist noch in Arbeit.</em></p><h2 id="_3-3-das-kartenfenster" tabindex="-1">3.3 Das Kartenfenster <a class="header-anchor" href="#_3-3-das-kartenfenster" aria-label="Permalink to &quot;3.3 Das Kartenfenster&quot;">​</a></h2><p>Ein Kartenfenster zeigen die Karte selbst sowie die Rohrzuordnung, die Mikrorohre, die Störungsanalyse, die Leitungsauskunft und die Wertermittlung. Es verhält sich überall gleich.</p><p>Mit dem Mausrad oder dem Touchpad zoomen Sie in die Karte hinein und heraus, mit gedrückter linker Maustaste verschieben Sie den Kartenausschnitt.</p><p>Links unten finden Sie den Regler „Transparenz“, mit dem Sie die <strong>Transparenz</strong> der Hintergrundkarte anpassen können. Dies ist hilfreich, um Netzdaten besser sichtbar zu machen.</p><p><img src="'+d+'" alt="Screenshot Karte mit Hervorhebung des Schiebereglers für die Transparenz der Karte" data-zoomable="true"></p><p>Auf der rechten Seite befindet sich die <strong>interaktive Legende</strong> („Layer“-Menü) mit den Einträgen „Adresse“, „Netzknoten“, „Trasse“, „Rohr“, „Gebiet“ und „OpenStreetMap“. Über die Symbole an den Einträgen können Sie:</p><ul><li>Objektarten (Layer) ein- oder ausblenden</li><li>Beschriftungen anzeigen oder verbergen</li><li>mit „Auf Ausdehnung zoomen“ die Ansicht auf alle Objekte eines Layers ausrichten</li><li>die Einträge „Netzknoten“ und „Gebiet“ über den kleinen Pfeil links aufklappen und die einzelnen Typen getrennt schalten</li><li>die Hintergrundkarte über den Eintrag „OpenStreetMap“ ausblenden oder in den Dunkelmodus wechseln</li></ul><p>Nicht jeder Eintrag bietet alle Möglichkeiten: Beim Eintrag „Rohr“ steht ausschließlich „Leitungsbeschriftungen anzeigen“ zur Verfügung.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Beschriftungen werden erst ab einer ausreichenden Zoomstufe eingeblendet. Wenn sich nach dem Einschalten nichts sichtbar ändert, zoomen Sie weiter in die Karte hinein.</p></div><p class="img-row"><img src="'+l+'" alt="Screenshot Karte mit Hervorhebung der Legende oben rechts" data-zoomable="true"><img src="'+h+'" alt="Vier Screenshots der Karte mit verschiedenen Einstellungen in der Legende" data-zoomable="true"></p><p>Mit „Auf Ausdehnung zoomen“ beim Eintrag „Adresse“ gelangen Sie in den Bereich, in dem für das gewählte Projekt Daten vorhanden sind.</p><p class="img-row"><img src="'+o+'" alt="Screenshot Karte mit Hervorhebung des Layers Adresse in der Legende rechts oben" data-zoomable="true"><img src="'+c+'" alt="Screenshot Karte nach dem Zoom auf die Ausdehnung des Layers Adresse" data-zoomable="true"></p><h2 id="_3-4-objekte-in-der-karte-suchen" tabindex="-1">3.4 Objekte in der Karte suchen <a class="header-anchor" href="#_3-4-objekte-in-der-karte-suchen" aria-label="Permalink to &quot;3.4 Objekte in der Karte suchen&quot;">​</a></h2><p>Oben links im Kartenfenster befindet sich eine <strong>Suchfunktion</strong>. Hier können Sie gezielt nach Adressen, Netzknoten, Trassen, Rohren und Gebieten suchen.</p><p><img src="'+u+'" alt="Screenshot Karte mit Hervorhebung des Suchfeldes oben links" data-zoomable="true"></p><p>Dazu gehen Sie folgendermaßen vor:</p><ol><li>Geben Sie einen Begriff oder einen Teil davon in das Suchfeld ein.</li><li>Drücken Sie Enter oder klicken Sie auf das Lupensymbol.</li><li>Die Trefferliste öffnet sich unterhalb des Suchfeldes und nennt die Anzahl der Treffer.</li><li>Jeder Treffer ist mit seiner Objektart gekennzeichnet.</li><li>Ab zehn Treffern erscheint im Kopf der Liste das Feld „Filtern“, mit dem Sie die Liste weiter einschränken.</li><li>Klicken Sie auf einen Treffer: Die Karte springt an die passende Stelle und das Objekt blinkt dreimal auf.</li></ol><p><img src="'+m+'" alt="Vier Screenshots des Suchablaufs in der Karte, nummeriert von 1 bis 6" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein Treffer öffnet den Infobereich <strong>nicht</strong>. Die Karte springt nur an die passende Stelle; klicken Sie das Objekt anschließend in der Karte an, um die Details zu sehen, siehe Kapitel <a href="./05-karte.html">Karte</a>.</p></div><h2 id="_3-5-strecke-und-flache-messen" tabindex="-1">3.5 Strecke und Fläche messen <a class="header-anchor" href="#_3-5-strecke-und-flache-messen" aria-label="Permalink to &quot;3.5 Strecke und Fläche messen&quot;">​</a></h2><p><em>Die Dokumentation zu diesem Abschnitt ist noch in Arbeit.</em></p><h2 id="_3-6-der-infobereich-mit-seinen-reitern" tabindex="-1">3.6 Der Infobereich mit seinen Reitern <a class="header-anchor" href="#_3-6-der-infobereich-mit-seinen-reitern" aria-label="Permalink to &quot;3.6 Der Infobereich mit seinen Reitern&quot;">​</a></h2><p>Wenn Sie ein Objekt auswählen, öffnet sich am rechten Rand eine Detailanzeige. Diese <strong>Info-Box</strong> überlagert die Ansicht, ohne den Kartenausschnitt oder die Tabelle darunter zu verändern. Welche Reiter sie enthält, hängt von der Objektart ab; „Eigenschaften“ und „Anhänge“ gibt es immer.</p><p>Die Angaben im Reiter „Eigenschaften“ sind je nach Ansicht nur zur Information oder bearbeitbar – in der Karte lesen Sie sie, in der Rohrverwaltung ändern Sie sie. Im Reiter „Aktionen“ finden Sie weiterführende Ansichten zum ausgewählten Objekt. Der Reiter „Anhänge“ ist überall bearbeitbar, siehe Abschnitt <a href="#_3-7-anhange-hochladen-ansehen-und-loschen">Anhänge hochladen, ansehen und löschen</a>.</p><p>Ist die Info-Box zu schmal, ziehen Sie sie am linken Rand über den Griff „Größe der Seitenleiste ändern“ breiter. Über das Kreuz „Seitenleiste schließen“ schließen Sie sie.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die eingestellte Breite gilt für alle Ansichten mit einer Info-Box, nicht nur für die, in der Sie sie geändert haben.</p></div><h2 id="_3-7-anhange-hochladen-ansehen-und-loschen" tabindex="-1">3.7 Anhänge hochladen, ansehen und löschen <a class="header-anchor" href="#_3-7-anhange-hochladen-ansehen-und-loschen" aria-label="Permalink to &quot;3.7 Anhänge hochladen, ansehen und löschen&quot;">​</a></h2><p>Zu Kartenobjekten, Rohren und Adressen können Sie Dateien ablegen; der Reiter „Anhänge“ steht deshalb bei allen diesen Objektarten zur Verfügung. Zum Hinzufügen klicken Sie im Bereich „Dateien hochladen“ auf „Dateien auswählen“ oder ziehen die Datei auf die Fläche „Dateien auswählen oder hierher ziehen“. Die maximale Dateigröße beträgt 50 MB.</p><p>Vorhandene Dateien stehen darunter im Bereich „Hochgeladene Dateien“, zusammengefasst in Ordnern, die nach ihrer Art benannt sind und die Anzahl enthalten, z. B. „documents (1)“. Klicken Sie auf einen Ordner, um ihn aufzuklappen – erst dann werden die einzelnen Dateien sichtbar. Zeigen Sie anschließend mit der Maus auf eine Datei, erscheinen rechts neben dem Dateinamen die Schaltflächen „Herunterladen“, „Umbenennen“ und „Datei löschen“; beim Löschen bestätigen Sie die Rückfrage.</p><p>Bei vielen Dateien hilft das Feld „Dateien suchen“ oberhalb der Liste. Sind die Schaltflächen nicht sichtbar, ist Ihr Fenster zu schmal: Scrollen Sie in der Info-Box nach rechts oder ziehen Sie die Box breiter.</p>',36),e("p",null,[e("video",{src:b,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/map_attachment.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),e("h2",{id:"_3-8-exportformate-im-uberblick",tabindex:"-1"},[n("3.8 Exportformate im Überblick "),e("a",{class:"header-anchor",href:"#_3-8-exportformate-im-uberblick","aria-label":'Permalink to "3.8 Exportformate im Überblick"'},"​")],-1),e("p",null,[e("em",null,"Die Dokumentation zu diesem Abschnitt ist noch in Arbeit.")],-1)])])}const w=t(p,[["render",g]]);export{D as __pageData,w as default};
